export default function issueNotionPrepare({ body, dataSourceId }) {
  const actions = ["opened", "edited", "deleted", "closed", "reopened"];
  const action = body?.action;
  if (!actions.includes(action))
    return {
      supported: false,
      opened: false,
      action: "ignored",
      dataSourceId: "",
      filter: {},
      parent: {},
      properties: {},
      trash: false,
    };
  const issue = body.issue;
  if (
    !issue ||
    !Number.isSafeInteger(issue.id) ||
    issue.id <= 0 ||
    typeof issue.title !== "string" ||
    !issue.title.trim() ||
    issue.title.length > 2000 ||
    typeof issue.html_url !== "string" ||
    !/^https:\/\/github\.com\//.test(issue.html_url)
  )
    throw Error("Invalid issue payload");
  if (
    typeof dataSourceId !== "string" ||
    !dataSourceId.trim() ||
    dataSourceId === "YOUR_NOTION_DATA_SOURCE_ID"
  )
    throw Error("Configure Notion data source ID");
  const properties =
    action === "opened"
      ? {
          Issue: { title: [{ text: { content: issue.title } }] },
          "Issue ID": { number: issue.id },
          Link: { url: issue.html_url },
          Closed: { checkbox: false },
        }
      : action === "edited"
        ? { Issue: { title: [{ text: { content: issue.title } }] } }
        : action === "closed"
          ? { Closed: { checkbox: true } }
          : action === "reopened"
            ? { Closed: { checkbox: false } }
            : {};
  return {
    supported: true,
    opened: action === "opened",
    action,
    dataSourceId,
    filter: { property: "Issue ID", number: { equals: issue.id } },
    parent: { data_source_id: dataSourceId },
    properties,
    trash: action === "deleted",
  };
}

