export default function issueNotionMatch({ result }) {
  if (!result || !Array.isArray(result.results) || typeof result.has_more !== "boolean")
    throw Error("Invalid Notion query response");
  if (result.has_more || result.results.length > 1)
    throw Error("More than one Notion page matches this issue");
  if (result.results.length === 0) return { found: false, pageId: "" };
  const page = result.results[0];
  if (page.object !== "page" || typeof page.id !== "string" || !page.id)
    throw Error("Invalid matching Notion page");
  return { found: true, pageId: page.id };
}
